import { http, HttpResponse } from "msw";
import { BASE_URL } from "../api/config";

const scopePathname =
  (typeof self !== "undefined" && self.registration && new URL(self.registration.scope).pathname) || "/";

const SCOPE = scopePathname.endsWith("/") ? scopePathname.slice(0, -1) : scopePathname;

// in-memory DB (로컬 기반)
const KEY = "WOODEN_MSW_DB_v1";
const seed = {
  sellercustomer: [
    {
      cusNo: 1, 
      cusComp: "판매처 A", 
      cusName: "홍길동", 
      cusEmail: "a@test.com", 
      cusPhone: "010-1111-2222", 
      cusAddr: "서울 강남구"
    }
  ],

  itemlist: [],

  orderlist: [
    {
      orderNo: 1, 
      orderDate: "2025-10-02", 
      cusComp: "판매처 A", 
      itemName: "완제품 A", 
      orderQty: 19, 
      orderPrice: 300000,
      orderState: "승인대기", 
      orderDeliState: "납품대기", 
      deliveryDate: "2025-10-24", 
      cusAddr: "주소", 
      totalPrice: 5700000
    }
  ],

  completed: [],

  seq: { cusNo: 1, orderNo: 1, itemNo: 0 }
};

const load = () => {
  try {
    return JSON.parse(localStorage.getItem(KEY)) || seed;
  } catch {
    return seed;
  };
};

const save = (db) => {
  localStorage.setItem (KEY, JSON.stringify(db));
  return db;
};

const table = (name) => (load()[name] || []);

const setTable = (name, rows) => {
  const db = load(); db[name] = rows;
  save(db);
  return rows;
};

const nextId = (field) => {
  const db = load();
  db.seq[field] = (db.seq[field] || 0) + 1;
  save(db);
  return db.seq[field];
};

const upsert = (name, row, pk) => {
  const rows = table(name);
  if (!row[pk])
    row[pk] = nextId(pk);
  
  const i = rows.findIndex(r => r[pk] === row[pk]);
  if (i >= 0) 
    rows[i] = { ...rows[i], ...row };
  else rows.push(row);
  setTable(name, rows);
  return row;
};

const remove = (name, pk, id) => setTable(name, table(name).filter(r => r[pk] !== id));

const clone = (v) => JSON.parse(JSON.stringify(v));

// 같은 엔드포인트를 '절대'와'상대' 둘 다 등록
const paths = (p) => {
  const clean = p.startsWith("/") ? p : `/${p}`;
  return [clean, `${SCOPE}${clean}`];
};

// 핸들러 시작
export const handlers = [
  // 판매거래처 목록
  ...paths("/order/sellercustomer").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("sellercustomer"))))
  ),

  // 판매거래처 등록
  ...paths("/order/sellercustomer").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("sellercustomer", body, "cusNo");   // 자동증가
      return HttpResponse.json(clone(saved));
    })
  ),

  // 판매거래처 수정/삭제
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert("sellercustomer", { ...body, cusNo: Number(params.cusNo) }, "cusNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("sellercustomer", "cusNo", Number(params.cusNo));
      return HttpResponse.json({ success: true });
    })
  ),

  // 상품 리스트 (드롭다운/목록)
  ...paths("/plan/itemlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("itemlist"))))
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert("itemlist", { ...body, itemNo: Number(params.itemNo) }, "itemNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/plan/itemlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("itemlist", body, "itemNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("itemlist", "itemNo", Number(params.itemNo));
      return HttpResponse.json({ success: true });
    })
  ),

  // 주문 리스트 (조회만)
  ...paths("/order/orderlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("orderlist"))))
  ),

  // 예측 시계열 (front의 forecastAPI.jsx에 맞춤)
  ...paths("/forecast/series").map((p) =>
    http.get(p, ({ request }) => {
      const url = new URL(request.url);
      const h = Number(url.searchParams.get("h") || 12);
      const now = new Date();
      const series = Array.from({ length: h }, (_, k) => ({
        date: new Date(now.getFullYear(), now.getMonth() + k + 1, 1).toISOString().slice(0, 7),
        value: 100 + 5 * k + Math.round(Math.random() * 8),
      }));
      return HttpResponse.json({ itemNo: Number(url.searchParams.get("itemNo") || 1), series });
    })
  ),
]
